class Solution {
public:
    int splitNum(int num) {
        int cnt[10] = {0};
        while (num > 0) { cnt[num % 10]++; num /= 10; }
        long long n1 = 0, n2 = 0;
        int turn = 0;
        for (int d = 0; d <= 9; d++) {
            while (cnt[d]-- > 0) {
                if (turn == 0) { n1 = n1 * 10 + d; turn = 1; }
                else { n2 = n2 * 10 + d; turn = 0; }
            }
        }
        return (int)(n1 + n2);
    }
};
